def idx_for_diag_se_from_tr(num_rows=2, num_cols=3):

    if num_rows <= num_cols:

        # upper right triangle
        for col in range(num_cols, num_cols-num_rows, -1):
            row = 0
            while col < num_cols:
                yield row, col
                row += 1
                col += 1

        # middle diagonals
        for col in range(num_cols-num_rows, -1, -1):
            row = 0
            while row < num_rows:
                yield row, col
                row += 1
                col += 1

        # lower left triangle
        for row in range(1, num_rows):
            col = 0
            while row < num_rows:
                yield row, col
                row += 1
                col += 1

    else:

        # upper right triangle
        for col in range(num_cols-1, 0, -1):
            row = 0
            while col < num_cols:
                yield row, col
                row += 1
                col += 1

        # middle diagonals
        for row in range(num_rows-num_cols+1):
            col = 0
            while col < num_cols:
                yield row, col
                row += 1
                col += 1

        # lower left triangle
        for row in range(num_rows-num_cols+1, num_rows):
            col = 0
            while row < num_rows:
                yield row, col
                row += 1
                col += 1

