def drains_to(grid, row, col):
    if row == 0:
        north = None
    else:
        north = grid[row-1][col]
    if row == len(grid)-1:
        south = None
    else:
        south = grid[row+1][col]
    if col == 0:
        west = None
    else:
        west = grid[row][col-1]
    if col == len(grid[0])-1:
        east = None
    else:
        east = grid[row][col+1]

    if north is None and south is None and east is None and west is None:
        return (None, None) # Hack in the 4-minute submission time
    current = grid[row][col]
    candidates = [val for val in [north, west, east, south] if val is not None and val < current]
    if not candidates:
        return (None, None)
    to_depth = min(candidates)
    if north == to_depth:
        return (row-1, col)
    elif west == to_depth:
        return (row, col-1)
    elif east == to_depth:
        return (row, col+1)
    elif south == to_depth:
        return (row+1, col)
    else:
        raise "Error in draining cell %s,%s" % (row, col)

