    prefix = short[:preidx]
    # 修复：sufidx 为负索引时，short[sufidx:-1] 会少一位，改为 short[sufidx:][:-1]
    suffix = short[sufidx:][:-1] if sufidx != 0 else short[:-1]
    middle = ['' if mc is None else next(miditer) for mc in ss]

    return prefix, suffix, middle

