def replace_repeated(child, aux, cut, subsize):
    SIZE = len(child)
    child = list(child)
    for i in range(SIZE):
        if i >= cut and i < cut + subsize:
            continue
        count = 0
        char = child[i]
        for j in range(SIZE):
            if child[j] == char:
                count += 1
        if count > 1:
            new_char = "\0"
            for j in range(subsize):
                candidate = aux[j]
                find = False
                for k in range(SIZE):
                    if child[k] == candidate:
                        find = True
                        break
                if not find:
                    new_char = candidate
                    break
            child[i] = new_char

    return "".join(child)

